def transform(grid):
    g=[row[:] for row in grid]
    # horizontal comb bars extend upward from each bar's broken positions to top edge;
    # vertical markers below are ignored for these rows. For each horizontal row, fill its zero gaps with own color.
    for r,row in enumerate(grid):
        nz=[v for v in row if v]
        if not nz: continue
        color=nz[0]
        # Complete row horizontal line (gap fill), preserving all colored segments.
        if sum(bool(v) for v in row)>=4:
            for c,v in enumerate(row):
                if v==0: g[r][c]=color
            # extend vertical upward at each gap position, from row-1 to top
            for c,v in enumerate(row):
                if v==0:
                    for rr in range(r):
                        if g[rr][c]==0: g[rr][c]=color
    return g

