    for r,row in enumerate(grid):
        if sum(bool(v) for v in row) < 5: continue
        # Each zero gap within a horizontal bar is assigned the nearest bar color.
        occupied=[c for c,v in enumerate(row) if v]
        if not occupied: continue
        gaps=[c for c in range(min(occupied),max(occupied)+1) if row[c]==0]
        for c in gaps:
