def transform(grid):
    g=[row[:] for row in grid]
    # Row gaps are bridged, and matching vertical columns continue above
    # and below the bar. The columns are encoded by each gap's adjacent colors.
    for r,row in enumerate(grid):
        nz=[c for c,v in enumerate(row) if v]
        if len(nz)<5: continue
        for c in range(min(nz),max(nz)+1):
            if row[c]: continue
            left=max(x for x in nz if x<c); right=min(x for x in nz if x>c)
            color=row[left] if left==min(nz) or row[left]==row[right] else row[right]
            # For a gap between the two distinct patterns, use the color of the closer run.
            if row[left]!=row[right]: color=row[right] if c-left > right-c else row[left]
            g[r][c]=color
            for rr in range(r):
                if g[rr][c]==0:g[rr][c]=color
            for rr in range(r+1,len(grid)):
                if g[rr][c]==0:g[rr][c]=color
    return g

