def transform(grid):
    """Tile the occupied cells with 2x2 squares and L-triominoes.

    The missing corner of an L determines its output color: upper-left=2,
    lower-left=3, upper-right=4, lower-right=1. A full square is color 1.
    """
    h, w = len(grid), len(grid[0])
    occupied = {(r, c) for r in range(h) for c in range(w) if grid[r][c] == 8}
    placements = []
    for r in range(h - 1):
        for c in range(w - 1):
            box = {(r, c), (r, c + 1), (r + 1, c), (r + 1, c + 1)}
            cells = box & occupied
            if len(cells) == 4:
                placements.append((cells, 1))
            elif len(cells) == 3:
                mr, mc = next(iter(box - cells))
                color = (2 if (mr, mc) == (r, c) else
                         3 if (mr, mc) == (r + 1, c) else
                         4 if (mr, mc) == (r, c + 1) else 1)
                placements.append((cells, color))

    def tile(remaining):
        if not remaining:
            return []
        cell = min(remaining)
        for cells, color in placements:
            if cell in cells and cells <= remaining:
                rest = tile(remaining - cells)
                if rest is not None:
                    return [(cells, color)] + rest
        return None

    pieces = tile(occupied)
    out = [[0] * w for _ in range(h)]
    if pieces is not None:
        for cells, color in pieces:
            for r, c in cells:
                out[r][c] = color
    return out

